#import <Foundation/Foundation.h>
#import <CoreText/CoreText.h>
#import <CoreGraphics/CoreGraphics.h>
static NSArray *runs(CTFontRef font) {
    CTFontDescriptorRef original=CTFontCopyFontDescriptor(font);
    NSDictionary *traits=CFBridgingRelease(CTFontCopyTraits(font));
    NSDictionary *fallback=@{(__bridge id)kCTFontFamilyNameAttribute:@"Noto Sans SC",(__bridge id)kCTFontTraitsAttribute:@{(__bridge id)kCTFontWeightTrait:traits[(__bridge id)kCTFontWeightTrait],(__bridge id)kCTFontSlantTrait:@0}};
    NSDictionary *attrs=@{(__bridge id)kCTFontCascadeListAttribute:@[fallback]};
    CTFontDescriptorRef fallbackDescriptor=CTFontDescriptorCreateWithAttributes((__bridge CFDictionaryRef)fallback);
    attrs=@{(__bridge id)kCTFontCascadeListAttribute:@[(__bridge id)fallbackDescriptor]};
    CTFontDescriptorRef desc=CTFontDescriptorCreateCopyWithAttributes(original,(__bridge CFDictionaryRef)attrs);
    CTFontRef copy=CTFontCreateCopyWithAttributes(font,15,NULL,desc);
    NSAttributedString *text=[[NSAttributedString alloc] initWithString:@"14.5万" attributes:@{(__bridge id)kCTFontAttributeName:(__bridge id)copy}];
    CTLineRef line=CTLineCreateWithAttributedString((__bridge CFAttributedStringRef)text);
    NSMutableArray *out=[NSMutableArray array];
    for(id object in (__bridge NSArray *)CTLineGetGlyphRuns(line)) {
        CTRunRef run=(__bridge CTRunRef)object;
        CTFontRef face=CFDictionaryGetValue(CTRunGetAttributes(run),kCTFontAttributeName);
        CFStringRef name=CTFontCopyPostScriptName(face);CFRange range=CTRunGetStringRange(run);
        [out addObject:@{@"font":(__bridge id)name,@"start":@(range.location),@"length":@(range.length)}];CFRelease(name);
    }
    CFRelease(line);CFRelease(copy);CFRelease(desc);CFRelease(fallbackDescriptor);CFRelease(original);return out;
}
int main(int argc,const char **argv) { @autoreleasepool {
    if(argc!=2)return 2;
    NSString *dir=[NSString stringWithUTF8String:argv[1]];
    NSArray *names=@[@"NotoSansSC-Regular.otf",@"NotoSansSC-Medium.otf",@"NotoSansSC-Bold.otf",@"Inter-Regular.ttf",@"Inter-Medium.ttf",@"Inter-SemiBold.ttf",@"Inter-Bold.ttf"];
    NSMutableArray *fonts=[NSMutableArray array],*faces=[NSMutableArray array];
    for(NSString *name in names) {
        NSData *data=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:name]];if(!data)return 3;
        CGDataProviderRef provider=CGDataProviderCreateWithCFData((__bridge CFDataRef)data);CGFontRef graphics=CGFontCreateWithDataProvider(provider);if(!graphics)return 4;
        CTFontRef font=CTFontCreateWithGraphicsFont(graphics,15,NULL,NULL);
        CFStringRef family=CTFontCopyFamilyName(font),postscript=CTFontCopyPostScriptName(font);CFDictionaryRef traits=CTFontCopyTraits(font);
        [faces addObject:@{@"file":name,@"family":(__bridge id)family,@"postscript":(__bridge id)postscript,@"native_weight":((__bridge NSDictionary *)traits)[(__bridge id)kCTFontWeightTrait]}];
        [fonts addObject:(__bridge id)font];CFRelease(traits);CFRelease(postscript);CFRelease(family);CFRelease(font);CGFontRelease(graphics);CGDataProviderRelease(provider);
    }
    NSArray *before=runs((__bridge CTFontRef)fonts[3]);NSMutableArray *registration=[NSMutableArray array];
    for(NSString *name in [names subarrayWithRange:NSMakeRange(0,3)]) {
        NSData *data=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:name]];
        CGDataProviderRef provider=CGDataProviderCreateWithCFData((__bridge CFDataRef)data);
        CGFontRef graphics=CGFontCreateWithDataProvider(provider);CFErrorRef error=NULL;
        bool ok=CTFontManagerRegisterGraphicsFont(graphics,&error);
        CGFontRelease(graphics);CGDataProviderRelease(provider);
        [registration addObject:@{@"file":name,@"process_scope":@YES,@"success":@(ok)}];if(error)CFRelease(error);
    }
    NSArray *after=runs((__bridge CTFontRef)fonts[3]);NSDictionary *result=@{@"faces":faces,@"before_name_cascade":before,@"after_process_registration_cascade":after,@"registration":registration,@"scope":@"Headless process-local font parsing and shaping only; no app, window, input or persistent font installation."};
    NSData *json=[NSJSONSerialization dataWithJSONObject:result options:NSJSONWritingPrettyPrinted error:NULL];fwrite(json.bytes,1,json.length,stdout);puts("");
}return 0;}
